What does the following program do when the input is unsigned 16 bit integer?<br><pre><code> #include &lt;stdio.h&gt;
main(){
  unsigned int num;
  int i;
  scanf("%u", &num);
  for(i=0;i<16;i++){
    printf("%d", (num &lt;&lt; i&1 &lt;&lt; 15)?1:0);
  }
}</code></pre>

What will be the output of the following C code?<br><pre><code> #include &lt;stdio.h&gt;
main()
{
    int i;
    for(i=0;i<5;i++)
    {
        int i=10;
        printf("%d" , i);
        i++;
    }
    return 0;
}</code></pre><br>

Consider the following function<br><pre><code> void swap(int a, int b)  
{       
    int temp;
    temp = a;
    a = b;
    b = temp;  
}  </code></pre>In order to exchange the values of two variables x and y.

What is the output of the C++ program?<br><pre><code> #include &lt;iostream&gt;
using namespace std;

void square(int *x){
    *x = (*x)++ * (*x);
}

void square(int *x, int *y){
    *x = (*x) * --(*y);
}

int main()
{
  int number = 30;
  square(&number, &number);
  cout &lt;&lt; number;
  return 0;
}</code></pre>
